'use strict';
const $=id=>document.getElementById(id),canvas=$('map'),ctx=canvas.getContext('2d');
const places={receiving:[130,130,'Recebimento',12],pallet:[400,130,'Pallet',18],rack:[660,130,'Depósito',6],sales:[400,340,'Expositor',6]};
function initial(){return {stock:{receiving:0,pallet:0,rack:0,sales:0,player:0,worker:0},orders:[],purchased:0,sold:0,cash:300,day:1,revenue:0,cost:0,purchases:0,missed:0,price:3,open:false,investment:'',task:'Parado',player:[130,260],worker:[650,280],dest:'pallet'}}
let s=initial(),target=null,timer=0,error=0,last=performance.now();
let cap=k=>k==='baskets'?6:k==='player'?(s.investment==='Carrinho'?3:1):k==='worker'?1:k==='sales'&&s.investment==='Expositor'?10:places[k][3];
let pending=()=>s.orders.reduce((n,o)=>n+o.pending,0);
let conserved=()=>Object.values(s.stock).reduce((a,b)=>a+b,0)+pending()+s.sold===s.purchased;
function move(a,b,n){let q=Math.max(0,Math.min(n,s.stock[a],cap(b)-s.stock[b]));if(a===b)return 0;s.stock[a]-=q;s.stock[b]+=q;return q}
function say(t,bad=false){$('note').textContent=t;const notice=$('menuNotice');if($('management').open&&notice){notice.textContent=t;notice.dataset.status=bad?'error':'success'}if(bad)error=1.4;update()}
function update(){$('hud').textContent=`Dia ${s.day} • ${s.open?'Aberta':'Fechada'}     $${s.cash.toFixed(2)}`;$('shop').textContent=s.open?'Fechar e ver resultado':'Abrir loja';$('load').textContent=`Sua carga: ${s.stock.player}/${cap('player')} caixas • Pendentes: ${pending()} • Vendidas: ${s.sold}`;$('priceText').textContent='$'+s.price.toFixed(2);if(!conserved())throw Error('Conservação de estoque violada')}
function near(){return Object.keys(places).find(k=>Math.hypot(s.player[0]-places[k][0],s.player[1]-places[k][1])<105)}
function modal(title,text){$('title').textContent=title;$('body').textContent=text;$('dialog').showModal()}
$('dismiss').onclick=()=>$('dialog').close();
canvas.onpointerdown=e=>{let r=canvas.getBoundingClientRect();target=[Math.max(25,Math.min(775,(e.clientX-r.left)*800/r.width)),Math.max(25,Math.min(435,(e.clientY-r.top)*460/r.height))];};
$('take').onclick=()=>{let k=near();say(k&&move(k,'player',cap('player'))?'Carga retirada. Caminhe até o destino e deposite.':'Aproxime-se de estoque disponível. Confira sua capacidade.',!k||s.stock.player===0)};
$('drop').onclick=()=>{let k=near(),q=k?move('player',k,s.stock.player):0;say(q?`${q} caixa(s) depositada(s).`:'Destino cheio, distante ou carga vazia. Mercadoria preservada.',!q)};
$('buy').onclick=()=>{if(s.cash<120)return say('Caixa insuficiente: pedido custa $120.',true);s.cash-=120;s.purchases+=120;s.purchased+=20;s.orders.push({total:20,received:0,pending:20});say('Pedido criado. Toque em Descarregar.')};
$('unload').onclick=()=>{let n=0;for(let o of s.orders){let q=Math.min(o.pending,12-s.stock.receiving);o.pending-=q;o.received+=q;s.stock.receiving+=q;n+=q}say(`${n} recebidas; ${pending()} pendentes. Transporte para liberar espaço.`,n===0)};
$('queue').onclick=()=>modal('Fila de entregas',s.orders.map((o,i)=>`Pedido ${i+1}: ${o.total} caixas\nRecebidas: ${o.received} • Pendentes: ${o.pending}`).join('\n\n')||'Nenhum pedido.');
$('task').onchange=e=>{s.task=e.target.value;say('Tarefa: '+s.task+'. Uma carga em trânsito será entregue antes da mudança.')};
$('price').oninput=e=>{s.price=Number(e.target.value);update()};
$('shop').onclick=()=>{if(!s.open){s.open=true;timer=0;say('Loja aberta. Abasteça o expositor para vender.');return}s.open=false;s.cash-=12;modal('Fechamento • dia '+s.day,`Receita: $${s.revenue.toFixed(2)}\nCMV: $${s.cost.toFixed(2)}\nCompras de estoque: $${s.purchases.toFixed(2)}\nDespesa diária: $12\nLucro operacional: $${(s.revenue-s.cost-12).toFixed(2)}\nCaixa: $${s.cash.toFixed(2)}\nTentativas sem estoque: ${s.missed}\n\nCompras reduzem caixa; o custo do estoque vendido entra no CMV. Investimentos ficam fora do lucro operacional.`);s.day++;s.revenue=s.cost=s.purchases=s.missed=0;update()};
function invest(kind){if(s.investment||s.cash<60)return say('Investimento já escolhido ou caixa insuficiente.',true);s.cash-=60;s.investment=kind;say(kind==='Carrinho'?'Carrinho equipado: transporte 3 caixas.':'Expositor ampliado para 10 caixas.')}
$('cart').onclick=()=>invest('Carrinho');$('shelf').onclick=()=>invest('Expositor');
$('save').onclick=()=>{try{localStorage.setItem('entre-mobile-02',JSON.stringify(s));say('Progresso salvo neste navegador.')}catch{say('Não foi possível salvar neste navegador.',true)}};
function valid(v){let base=initial();if(!v||typeof v!=='object')return false;for(let k of Object.keys(base))if(typeof v[k]!==typeof base[k])return false;if(!['','Carrinho','Expositor'].includes(v.investment)||!['Parado','Transportar','Repor'].includes(v.task)||!places[v.dest])return false;if(!Array.isArray(v.orders)||!v.stock)return false;for(let k of Object.keys(base.stock))if(!Number.isInteger(v.stock[k])||v.stock[k]<0)return false;for(let k of ['cash','day','revenue','cost','purchases','missed','price','purchased','sold'])if(!Number.isFinite(v[k]))return false;if(v.price<1||v.price>5||v.day<1)return false;for(let k of ['player','worker'])if(!Array.isArray(v[k])||v[k].length!==2||!v[k].every(Number.isFinite))return false;for(let o of v.orders)if(!o||!['total','received','pending'].every(k=>Number.isInteger(o[k])&&o[k]>=0)||o.total!==o.received+o.pending)return false;let old=s;s=v;let ok=Object.keys(base.stock).every(k=>v.stock[k]<=cap(k))&&conserved();s=old;return ok}
$('restore').onclick=()=>{try{let v=JSON.parse(localStorage.getItem('entre-mobile-02'));if(!valid(v))throw Error();s=v;target=null;timer=0;$('task').value=s.task;$('price').value=s.price;say('Progresso carregado.')}catch{say('Nenhum salvamento válido. Estado atual preservado.',true)}};
function walk(pos,to,speed,dt){let d=Math.hypot(to[0]-pos[0],to[1]-pos[1]);if(d<2)return true;let a=Math.min(1,speed*dt/d);pos[0]+=(to[0]-pos[0])*a;pos[1]+=(to[1]-pos[1])*a;return false}
function step(dt){if(target&&walk(s.player,target,210,dt))target=null;if(s.stock.worker){let p=places[s.dest];if(walk(s.worker,[p[0],p[1]+55],125,dt))move('worker',s.dest,1)}else{let a,b;if(s.task==='Transportar'){a='receiving';b=s.stock.pallet<18?'pallet':'rack'}if(s.task==='Repor'){a=s.stock.pallet?'pallet':'rack';b='sales'}if(a&&s.stock[a]&&s.stock[b]<cap(b)){let p=places[a];if(walk(s.worker,[p[0],p[1]+55],125,dt)){move(a,'worker',1);s.dest=b}}}if(s.open){timer+=dt;if(timer>=2+s.price){timer=0;if(s.stock.sales){s.stock.sales--;s.sold++;s.cash+=s.price*6;s.revenue+=s.price*6;s.cost+=6}else s.missed++}}error=Math.max(0,error-dt);update()}
function draw(){ctx.clearRect(0,0,800,460);ctx.strokeStyle='#405958';for(let x=0;x<800;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,460);ctx.stroke()}for(let y=0;y<460;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(800,y);ctx.stroke()}for(let [k,p] of Object.entries(places)){ctx.fillStyle='#18363b';ctx.fillRect(p[0]-90,p[1]-35,180,85);ctx.strokeStyle=k==='sales'?'#8ecfb0':'#dfb66e';ctx.strokeRect(p[0]-90,p[1]-35,180,85);ctx.fillStyle='#f5e9cf';ctx.font='bold 22px system-ui';ctx.textAlign='center';ctx.fillText(p[2],p[0],p[1]-50);ctx.font='20px system-ui';ctx.fillText(`${s.stock[k]}/${cap(k)} caixas`,p[0],p[1]+78);for(let i=0;i<s.stock[k];i++){ctx.fillStyle=k==='sales'?'#8ecfb0':'#dfb66e';ctx.fillRect(p[0]-78+i%6*26,p[1]-25+Math.floor(i/6)*23,20,18)}}for(let [k,col,label] of [['worker','#f0b469','Funcionário'],['player','#7bcfed','Você']]){let p=s[k];ctx.fillStyle=col;ctx.fillRect(p[0]-12,p[1]-10,24,30);ctx.fillStyle='#f0cba4';ctx.fillRect(p[0]-9,p[1]-28,18,18);ctx.fillStyle='#fff';ctx.font='17px system-ui';ctx.fillText(label,p[0],p[1]+42);if(s.stock[k]){ctx.fillStyle='#ddb165';ctx.fillRect(p[0]+12,p[1]-8,20,20)}}if(error){ctx.fillStyle='#ff7777';ctx.font='bold 30px system-ui';ctx.fillText('X',s.player[0],s.player[1]-40)}if(target){ctx.strokeStyle='#8dd8e8';ctx.beginPath();ctx.arc(...target,9,0,Math.PI*2);ctx.stroke()}}
function frame(now){let dt=Math.min((now-last)/1000,.05);last=now;if(!document.hidden&&!$('dialog').open&&!$('management').open)step(dt);draw();requestAnimationFrame(frame)}say('Toque no mapa para caminhar. Comece comprando 20 caixas.');requestAnimationFrame(frame);
